function f = HS51_f(x)
f = (x(1) - x(2)).^2 + (x(4) - 1).^2 + (x(5) - 1).^2 + (x(2) + x(3) - 2).^2;
end

function g = HS51_g(x)
g = zeros(5, 1);
g(1) = 2*x(1) - 2*x(2);
g(2) = -2*x(1) + 4*x(2) + 2*x(3) - 4;
g(3) = 2*x(2) + 2*x(3) - 4;
g(4) = 2*x(4) - 2;
g(5) = 2*x(5) - 2;
end

function c = HS51_c(x)
c = zeros(3, 1);
c(1) = x(1) + 3*x(2) - 4;
c(2) = x(3) + x(4) - 2*x(5);
c(3) = x(2) - x(5);
end

